for (const item of $input.all()) {
  if (item.binary && item.binary.data) {
    item.binary.data.mimeType = 'audio/mp4';
    item.binary.data.fileExtension = 'm4a';
    item.binary.data.fileName = 'audio.m4a';
  }
}
return $input.all();

return items.map(item => {
  // আপনার স্ক্রিনশট অনুযায়ী ডাটাটি সরাসরি 'action' ফিল্ডে আছে
  const rawData = item.json.action;

  if (rawData) {
    // ডাটাটিকে নতুন লাইন (\n) দিয়ে ভাগ করা হচ্ছে
    const parts = rawData.split('\n');

    return {
      json: {
        action_type: parts[0].trim(), // আউটপুট: "delete" বা "keep"
        comment_id: parts[1] ? parts[1].trim() : "", // আউটপুট: আইডিটি
        original_data: rawData
      }
    };
  } else {
    // যদি ডাটা না থাকে তবে এরর এড়াতে খালি অবজেক্ট দিবে
    return { json: { error: "No action data found" } };
  }
});

